Local Ltac r2v X d0 t b0 b1 b2 rest Eb0 Et Eb1 WIN PASS V R10 R12 R23 R24 :=
  lazymatch goal with |- goal_from _ ?fx ?R _ =>
    runpk X fx R (fun j => match j with 2%nat => S | 33%nat => d0 | 34%nat => d0 + t + 1 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0 | 39%nat => b2 | _ => 0 end)
      ltac:(fun EX =>
    destruct EX as [EX|EX]; msks EX;
    [ cexit_err d0 b0 t Eb0 Et WIN V
    | gpre; lazymatch goal with CB : 128 <= b2 < 192 |- _ =>
        apply (r1_case _ _ d0 t b0 b1 (b2 :: rest) ltac:(lia) ltac:(lia) ltac:(lia) Eb0 Et Eb1 WIN (PASS CB));
        [vk V| kept 10%nat R10| assumption| kept 12%nat R12| kept 23%nat R23| kept 24%nat R24] end ])
  end.
Lemma r2_case fx R d0 t b0 b1 b2 rest :
  p <= c <= d0 -> 2 <= t <= 3 -> d0 + t + 1 <= e -> b0 = bat l (d0 - p) -> t = utf8_trail b0 -> b1 = bat l (d0 - p + 1) -> b2 = bat l (d0 - p + 2) ->
  firstn (Z.to_nat (t + 1)) (skipn (Z.to_nat (d0 - p)) l) = b0 :: b1 :: b2 :: rest ->
  (128 <= b2 < 192 -> 128 <= b1 < 192 -> second_ok b0 b1 -> lead_ok b0 -> utf8_legal (b0 :: b1 :: b2 :: rest) = true) ->
  vconst R -> getr R (reg 10) = Z_to_bv 64 d0 -> getr R (reg 26) = Z_to_bv 64 (d0 + 3) -> getr R (reg 12) = Z_to_bv 64 (d0 + t + 1) ->
  getr R (reg 23) = Z_to_bv 64 (sx8u b0) -> getr R (reg 24) = Z_to_bv 64 b0 -> goal_from d0 fx R 0xb1258.
Proof using All.
